/**
 * GET/POST /cron/generate-trivia-questions
 *
 * Phase 49 (2026-05-05) rewrite — two-track refill pipeline.
 *
 * **Track A (deterministic, $0):** strategy categories generated from
 * `solved_spots_gold` + `memory_charts_gold` via the same engine training
 * games use. NO Grok involvement.
 *   gto_theory, gto_scenarios, cash_game_situations, mtt_situations, icm_chip_ev
 *
 * **Track B (Grok-3 + validator gate):** fact categories generated by Grok
 * with a 5-layer validator and 60-day dedup.
 *   poker_history, famous_hands, player_profiles, tournament_facts, rule_knowledge
 *
 * Each run does up to MAX_BATCHES_PER_RUN batches across all categories,
 * preferring the most-undertarget category each iteration. Track A batches
 * are nearly free (no Grok call). Track B batches cost ~$0.002 each.
 *
 * Auth: /cron/* middleware chain (Bearer CRON_SECRET).
 *
 * Env vars required:
 *   XAI_API_KEY (Track B only)
 *   NEXT_PUBLIC_SUPABASE_URL
 *   SUPABASE_SERVICE_ROLE_KEY
 */
import type { Context } from 'hono';
import { getSupabase } from '../lib/supabase.js';
import { getGrokClient } from '../lib/grok.js';
import { validateBatch, type TriviaQuestion } from '../lib/triviaValidator.js';

// ─── Configuration ─────────────────────────────────────────────────────────

const TARGET_PER_CATEGORY = 1500;
const DIFFICULTY_DISTRIBUTION: Record<string, number> = { easy: 20, medium: 50, hard: 30 };
const MAX_BATCHES_PER_RUN = 6; // up to 6 batches per cron tick
const TRACK_A_BATCH_SIZE = 100; // deterministic: lots, fast
const TRACK_B_BATCH_SIZE = 10;  // Grok: small, cost-controlled

const TRACK_A_CATEGORIES = ['gto_theory', 'gto_scenarios', 'cash_game_situations', 'mtt_situations', 'icm_chip_ev'];
const TRACK_B_CATEGORIES = ['poker_history', 'famous_hands', 'player_profiles', 'tournament_facts', 'rule_knowledge'];

// ─── Track A — deterministic helpers (ported from scripts/trivia-deterministic-seed.js) ──

const RANK_VAL: Record<string, number> = {
  '2':0,'3':1,'4':2,'5':3,'6':4,'7':5,'8':6,'9':7,'T':8,'J':9,'Q':10,'K':11,'A':12,
};

const ACTION_LABELS: Record<string, string> = {
  c:'Check', x:'Check', f:'Fold', fold:'Fold', push:'Push All-In',
  b16:'Bet 16% pot', b20:'Bet 20% pot', b25:'Bet 25% pot', b33:'Bet 33% pot',
  b40:'Bet 40% pot', b45:'Bet 45% pot', b50:'Bet 50% pot', b55:'Bet 55% pot',
  b60:'Bet 60% pot', b66:'Bet 67% pot', b75:'Bet 75% pot', b80:'Bet 80% pot',
  b100:'Bet pot', b125:'Bet 125% pot', b150:'Overbet 150%', b200:'Overbet 200%',
  b300:'Overbet 300%', allin:'All-In', r:'Raise',
};

const VILLAIN_MAP: Record<string, string> = {
  BTN:'BB', SB:'BB', BB:'BTN', UTG:'BB', MP:'BB', CO:'BTN', HJ:'CO', 'UTG+1':'BB', 'MP+1':'BB',
};

function getActionLabel(code: string): string {
  if (ACTION_LABELS[code]) return ACTION_LABELS[code]!;
  const bm = code.match(/^b(\d+)$/);
  if (bm) return `Bet ${bm[1]}% pot`;
  const rm = code.match(/^r(\d+)$/);
  if (rm) return `Raise ${rm[1]}%`;
  return code.toUpperCase();
}

function parseBoardFromHash(hash: string): string[] {
  if (!hash) return [];
  const parts = hash.split('_');
  const boardStr = parts[parts.length - 1] || '';
  if (boardStr.length < 4) return [];
  const cards: string[] = [];
  for (let i = 0; i < boardStr.length; i += 2) {
    if (i + 1 < boardStr.length) {
      const card = boardStr.substring(i, i + 2);
      if (/^[2-9TJQKA][shdc]$/i.test(card)) cards.push(card);
    }
  }
  return cards;
}

function extractPositionFromHash(hash: string): string {
  if (!hash) return 'BTN';
  const POSITIONS = ['BTN', 'SB', 'BB', 'UTG', 'MP', 'CO', 'HJ'];
  for (const part of hash.split('_')) {
    if (POSITIONS.includes(part.toUpperCase())) return part.toUpperCase();
  }
  return 'BTN';
}

function hashSeed(str: string): number {
  let h = 0;
  for (let i = 0; i < str.length; i++) { h = ((h << 5) - h) + str.charCodeAt(i); h |= 0; }
  return Math.abs(h);
}

function classifyDifficulty(maxFreq: number): string {
  if (maxFreq >= 0.80) return 'easy';
  if (maxFreq <= 0.55) return 'hard';
  return 'medium';
}

interface DetQuestion {
  question: string;
  options: string[];
  correct_index: number;
  explanation: string;
  difficulty: string;
  subcategory: string;
}

function buildDetQuestionFromScenario(scenario: any, idx: number, category: string): DetQuestion | null {
  const sm = scenario.strategy_matrix || {};
  const actions: string[] = sm.actions || [];
  const frequencies: Record<string, Record<string, number>> = sm.frequencies || {};
  if (actions.length === 0) return null;

  const sampleAction = actions.find(a => frequencies[a]) || actions[0]!;
  const handFreqs = frequencies[sampleAction] || {};
  const allHands = Object.keys(handFreqs).filter(h => {
    if (!h || h.length < 2) return false;
    return actions.some(a => {
      const f = frequencies[a]?.[h];
      return typeof f === 'number' && f > 0;
    });
  });
  if (allHands.length === 0) return null;

  const seed = hashSeed(`${scenario.scenario_hash || scenario.id}_${idx}`);
  const heroHand = allHands[seed % allHands.length]!;

  const handActions: Record<string, number> = {};
  const validActions: string[] = [];
  let optimalAction = '';
  let maxFreq = -1;
  for (const a of actions) {
    const f = frequencies[a]?.[heroHand];
    if (typeof f === 'number' && f >= 0 && f <= 1) {
      handActions[a] = f;
      validActions.push(a);
      if (f > maxFreq) { maxFreq = f; optimalAction = a; }
    }
  }
  if (!optimalAction || validActions.length === 0) return null;

  const gtoFrequencies: Record<string, number> = {};
  for (const a of validActions) gtoFrequencies[a] = Math.round((handActions[a] || 0) * 100);
  const total = Object.values(gtoFrequencies).reduce((s, v) => s + v, 0);
  if (total > 0 && total !== 100) {
    for (const k of Object.keys(gtoFrequencies)) gtoFrequencies[k] = Math.round(gtoFrequencies[k]! * 100 / total);
    const newTotal = Object.values(gtoFrequencies).reduce((s, v) => s + v, 0);
    if (newTotal !== 100) gtoFrequencies[optimalAction] = (gtoFrequencies[optimalAction] || 0) + (100 - newTotal);
  }

  const optionsArr = validActions.slice(0, 4).map(a => ({ id: a, text: getActionLabel(a) }));
  const allFillers = ['f', 'c', 'b33', 'b75', 'allin', 'r', 'b50', 'b100'];
  while (optionsArr.length < 4) {
    const fa = allFillers.find(x => !optionsArr.some(o => o.id === x));
    if (!fa) break;
    optionsArr.push({ id: fa, text: getActionLabel(fa) });
  }
  if (optionsArr.length < 4) return null;

  const board = parseBoardFromHash(scenario.scenario_hash || '');
  const heroPos = extractPositionFromHash(scenario.scenario_hash || '');
  const street = scenario.street || 'flop';

  const freqPct = (maxFreq * 100).toFixed(0);
  let explanation: string;
  if (maxFreq >= 0.95) {
    explanation = `GTO solver: Pure ${getActionLabel(optimalAction)} (${freqPct}%). ${heroHand} has a clear optimal line on the ${street}.`;
  } else {
    const mixedParts = validActions
      .filter(a => (handActions[a] || 0) > 0.01)
      .sort((a, b) => (handActions[b] || 0) - (handActions[a] || 0))
      .map(a => `${getActionLabel(a)} ${((handActions[a] || 0) * 100).toFixed(0)}%`)
      .join(', ');
    explanation = `GTO solver mixes: ${mixedParts}. Primary line is ${getActionLabel(optimalAction)} at ${freqPct}%.${maxFreq < 0.6 ? ' This is a close GTO spot.' : ''}`;
  }
  if (board.length > 0) explanation = `Board: ${board.join(' ')}. ${explanation}`;

  const questionText = street === 'preflop'
    ? `You hold ${heroHand} in ${heroPos} preflop (${scenario.stack_depth || 100}BB). What is the GTO play?`
    : `You hold ${heroHand} on the ${street}. Board: ${board.join(' ')}. What is the GTO play?`;

  const correctIdx = optionsArr.findIndex(o => o.id === optimalAction);
  if (correctIdx < 0) return null;

  return {
    question: questionText,
    options: optionsArr.map(o => o.text),
    correct_index: correctIdx,
    explanation,
    difficulty: classifyDifficulty(maxFreq),
    subcategory: `det:${scenario.scenario_hash || scenario.id}:${heroHand}`,
  };
}

