async function fetchScenarioPool(category: string, page = 0, pageSize = 1000): Promise<any[]> {
  const sources = TRACK_A_SOURCES[category] || [];
  if (sources.length === 0) return [];
  // Pick a source by category-and-tick variety
  const src = sources[(page + Date.now() / 1000 / 60 | 0) % sources.length]!;
  const sb = getSupabase();
  const select = 'id,scenario_hash,street,stack_depth,game_type,strategy_matrix';
  // Hono supabase wrapper: use `from(...).select(...)` rather than raw url
  // Filter is in URL form "&game_type=eq.X&street=eq.Y" — parse to chain
  let query = sb.from(src.table).select(select);
  for (const part of src.filter.split('&').filter(Boolean)) {
    const [col, expr] = part.split('=');
    if (!col || !expr) continue;
    if (expr.startsWith('eq.')) query = query.eq(col, expr.slice(3));
  }
  const { data, error } = await query.range(page * pageSize, (page + 1) * pageSize - 1);
  if (error) {
    console.warn(`[trivia/track-A] pool fetch error for ${category}: ${error.message}`);
    return [];
  }
  return data || [];
}

async function generateTrackABatch(category: string, target: number, existing: Set<string>): Promise<TriviaQuestion[]> {
  // Try up to 3 pool pages to gather enough new questions
  const out: TriviaQuestion[] = [];
  for (let page = 0; page < 3 && out.length < target; page++) {
    const pool = await fetchScenarioPool(category, page);
    if (pool.length === 0) break;
    for (let i = 0; i < pool.length * 4 && out.length < target; i++) {
      const sc = pool[i % pool.length];
      const q = buildDetQuestionFromScenario(sc, Math.floor(i / pool.length), category);
      if (!q) continue;
      if (existing.has(q.subcategory)) continue;
      existing.add(q.subcategory);
      out.push({
        category,
        difficulty: q.difficulty,
        question: q.question,
        options: q.options,
        correct_index: q.correct_index,
        explanation: q.explanation,
        subcategory: q.subcategory,
        created_at: new Date().toISOString(),
        last_used_at: null,
      } as TriviaQuestion);
    }
  }
  return out;
}

