const AG1_SYSTEM_PROMPT = `You are a poker historian and rules expert generating trivia questions. Output ONLY valid JSON. Be FACTUALLY ACCURATE — every fact must be verifiable from public sources.`;

async function generateTrackBBatch(category: CategoryDef, subcategory: string, difficulty: string, count: number): Promise<TriviaQuestion[]> {
  const grok = getGrokClient();
  const prompt = `Generate exactly ${count} unique poker trivia questions.

CATEGORY: ${category.name}
TOPIC FOCUS: ${subcategory}
DIFFICULTY: ${difficulty}

Rules:
- Each question has exactly 4 multiple-choice options
- Exactly one option is correct (set correct_index 0-3)
- The correct answer must be 100% factually verifiable from public sources
- Distractors must be plausible but clearly wrong (no joke answers)
- "${difficulty}" means: easy = casual fans know it; medium = enthusiasts know it; hard = serious students of the game
- Provide a 1-2 sentence explanation citing a specific source/event/year
- Avoid duplicating well-known questions

Return ONLY this JSON shape (no markdown, no extra text):
{"questions":[{"question":"...","options":["A","B","C","D"],"correct_index":0,"explanation":"...","subcategory":"${subcategory}"}]}`;

  try {
    const response = await grok.chat.completions.create({
      model: 'grok-3-mini',
      messages: [
        { role: 'system', content: AG1_SYSTEM_PROMPT },
        { role: 'user', content: prompt },
      ],
      response_format: { type: 'json_object' },
      temperature: 0.7,
      max_tokens: 4000,
      // @ts-expect-error reasoning_effort is xAI-specific
      reasoning_effort: 'low',
    });

    const content = response.choices[0]?.message?.content;
    if (!content) return [];
    const parsed = JSON.parse(content);
    const questions: any[] = Array.isArray(parsed) ? parsed : parsed.questions || [];

    return questions
      .filter(q =>
        q.question && q.options?.length === 4 &&
        typeof q.correct_index === 'number' && q.correct_index >= 0 && q.correct_index <= 3 &&
        q.explanation && q.explanation.length > 30,
      )
      .map(q => ({
        category: category.id,
        difficulty,
        question: q.question.trim(),
        options: q.options.map((o: string) => o.trim()),
        correct_index: q.correct_index,
        explanation: q.explanation.trim(),
        subcategory: `grok:${subcategory.slice(0, 60)}`,
        created_at: new Date().toISOString(),
        last_used_at: null,
      }));
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    console.warn(`[trivia/track-B] generation error ${category.name}/${subcategory}/${difficulty}: ${msg}`);
    return [];
  }
}

async function checkForDuplicates(newQuestion: string, category: string): Promise<boolean> {
  const keywords = newQuestion.toLowerCase().replace(/[^a-z0-9\s]/g, '').split(' ').filter(w => w.length > 4).slice(0, 5);
  if (keywords.length === 0) return false;
  const { data: existing } = await getSupabase()
    .from('trivia_questions').select('question').eq('category', category).limit(500);
  if (!existing) return false;
  for (const eq of existing as { question: string }[]) {
    const ew = eq.question.toLowerCase().replace(/[^a-z0-9\s]/g, '').split(' ').filter(w => w.length > 4);
    const overlap = keywords.filter(k => ew.includes(k)).length;
    if (overlap >= 3 || (keywords.length <= 3 && overlap === keywords.length)) return true;
  }
  return false;
}

// ─── Pool stats ───────────────────────────────────────────────────────────

interface PoolStat {
  total: number;
  easy: number;
  medium: number;
  hard: number;
}

async function getPoolStats(): Promise<Record<string, PoolStat>> {
  const stats: Record<string, PoolStat> = {};
  const allCategories = [...TRACK_A_CATEGORIES, ...TRACK_B_CATEGORIES];

  for (const catId of allCategories) {
    const sb = getSupabase();
    const { count: total } = await sb.from('trivia_questions').select('*', { count: 'exact', head: true }).eq('category', catId);
    const { count: easy } = await sb.from('trivia_questions').select('*', { count: 'exact', head: true }).eq('category', catId).eq('difficulty', 'easy');
    const { count: medium } = await sb.from('trivia_questions').select('*', { count: 'exact', head: true }).eq('category', catId).eq('difficulty', 'medium');
    const { count: hard } = await sb.from('trivia_questions').select('*', { count: 'exact', head: true }).eq('category', catId).eq('difficulty', 'hard');
    stats[catId] = { total: total ?? 0, easy: easy ?? 0, medium: medium ?? 0, hard: hard ?? 0 };
  }
  return stats;
}

interface NeedItem {
  categoryId: string;
  difficulty: 'easy' | 'medium' | 'hard';
  needed: number;
  track: 'A' | 'B';
}

function determineNeeds(stats: Record<string, PoolStat>): NeedItem[] {
  const needs: NeedItem[] = [];
  for (const catId of [...TRACK_A_CATEGORIES, ...TRACK_B_CATEGORIES]) {
    const s = stats[catId];
    if (!s || s.total >= TARGET_PER_CATEGORY) continue;
    const track = TRACK_A_CATEGORIES.includes(catId) ? 'A' : 'B';
    for (const [diff, pct] of Object.entries(DIFFICULTY_DISTRIBUTION)) {
      const targetCount = Math.floor(TARGET_PER_CATEGORY * pct / 100);
      const current = s[diff as 'easy' | 'medium' | 'hard'];
      const needed = Math.max(0, targetCount - current);
      if (needed > 0) needs.push({ categoryId: catId, difficulty: diff as any, needed, track });
    }
  }
  // Prioritize biggest gaps first; within a tie, prefer Track A (free)
  needs.sort((a, b) => {
    if (a.needed !== b.needed) return b.needed - a.needed;
    return a.track === 'A' ? -1 : 1;
  });
  return needs;
}

// ─── Hono handler ─────────────────────────────────────────────────────────

export async function generateTriviaQuestions(c: Context) {
  const startTs = Date.now();
  try {
    const stats = await getPoolStats();
    const totalNow = Object.values(stats).reduce((s, v) => s + v.total, 0);
    const targetTotal = (TRACK_A_CATEGORIES.length + TRACK_B_CATEGORIES.length) * TARGET_PER_CATEGORY;

    if (totalNow >= targetTotal) {
      return c.json({ success: true, message: 'pool complete', totalNow, targetTotal, stats });
    }

    const needs = determineNeeds(stats);
    if (needs.length === 0) return c.json({ success: true, message: 'all categories at target', stats });

    let generated = 0;
    let trackACalls = 0;
    let trackBCalls = 0;
    const results: any[] = [];

    // Subcategory dedup cache per Track A category (loaded lazily)
    const detExisting: Record<string, Set<string>> = {};

    for (let batch = 0; batch < MAX_BATCHES_PER_RUN && batch < needs.length; batch++) {
      const need = needs[batch]!;

      if (need.track === 'A') {
        // Track A — deterministic
        if (!detExisting[need.categoryId]) {
          const { data } = await getSupabase()
            .from('trivia_questions').select('subcategory').eq('category', need.categoryId).like('subcategory', 'det:%').limit(5000);
          detExisting[need.categoryId] = new Set((data || []).map((r: any) => r.subcategory).filter(Boolean));
        }
        const want = Math.min(TRACK_A_BATCH_SIZE, need.needed);
        const allQs = await generateTrackABatch(need.categoryId, want * 3, detExisting[need.categoryId]!);
        // Filter to the desired difficulty bucket
        const qs = allQs.filter(q => q.difficulty === need.difficulty).slice(0, want);
        if (qs.length > 0) {
          const { valid: validQs, rejected } = validateBatch(qs);
          if (rejected.length > 0) console.warn(`[trivia/track-A] ${need.categoryId} rejected ${rejected.length} questions`);
          if (validQs.length > 0) {
            const { data, error } = await getSupabase().from('trivia_questions').insert(validQs).select();
            if (error) console.warn(`[trivia/track-A] insert error: ${error.message}`);
            else {
              generated += data?.length ?? 0;
              results.push({ track: 'A', category: need.categoryId, difficulty: need.difficulty, generated: data?.length ?? 0 });
            }
          }
        }
        trackACalls++;
      } else {
        // Track B — Grok
        const catDef = TRACK_B_CATEGORIES_DEF.find(c => c.id === need.categoryId);
        if (!catDef) continue;
        const subcat = catDef.subcategories[Math.floor(Math.random() * catDef.subcategories.length)]!;
        const want = Math.min(TRACK_B_BATCH_SIZE, need.needed);
        const qs = await generateTrackBBatch(catDef, subcat, need.difficulty, want);
        const uniqueQs: TriviaQuestion[] = [];
        for (const q of qs) {
          if (!(await checkForDuplicates(q.question, need.categoryId))) uniqueQs.push(q);
        }
        if (uniqueQs.length > 0) {
          const { valid: validQs, rejected } = validateBatch(uniqueQs);
          if (rejected.length > 0) console.warn(`[trivia/track-B] ${need.categoryId}/${subcat} rejected ${rejected.length}`);
          if (validQs.length > 0) {
            const { data, error } = await getSupabase().from('trivia_questions').insert(validQs).select();
            if (error) console.warn(`[trivia/track-B] insert error: ${error.message}`);
            else {
              generated += data?.length ?? 0;
              results.push({ track: 'B', category: need.categoryId, subcategory: subcat, difficulty: need.difficulty, generated: data?.length ?? 0 });
            }
          }
        }
        trackBCalls++;
      }

      if (batch < MAX_BATCHES_PER_RUN - 1) await new Promise(r => setTimeout(r, 500));
    }

    const after = await getPoolStats();
    const newTotal = Object.values(after).reduce((s, v) => s + v.total, 0);

    return c.json({
      success: true,
      generated,
      trackACalls,
      trackBCalls,
      previousTotal: totalNow,
      newTotal,
      targetTotal,
      progress: `${Math.round((newTotal / targetTotal) * 100)}%`,
      elapsedMs: Date.now() - startTs,
      results,
      stats: after,
    });
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    console.warn('[generate-trivia-questions] fatal:', msg);
    return c.json({ success: false, error: msg }, 500);
  }
}
